import matplotlib.pyplot as plt

def category_counts(items):
    counts = {}
    for it in items:
        counts[it] = counts.get(it, 0) + 1
    return counts

data = ["apple", "banana", "apple", "cherry", "banana", "apple"]
counts = category_counts(data)
plt.bar(list(counts.keys()), list(counts.values()))
plt.title("Fruit counts"); plt.ylabel("count")

import matplotlib.pyplot as plt

def monthly_totals(pairs):
    totals = {}
    for month, amount in pairs:
        totals[month] = totals.get(month, 0) + amount
    return totals

sales = [("Jan", 100), ("Feb", 80), ("Jan", 50), ("Mar", 30), ("Feb", 20)]
totals = monthly_totals(sales)
plt.bar(list(totals.keys()), list(totals.values()))
plt.title("Monthly totals"); plt.ylabel("amount")
